create function cms_private.matches_shape(v jsonb,s jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare item record; field record;
begin
 if v is null or jsonb_typeof(v) is distinct from s->>'type' then return false;end if;
 if s->>'type'='object' then
  for item in select key,value from jsonb_each(v) loop
   if not (s->'properties' ? item.key) or not cms_private.matches_shape(item.value,s->'properties'->item.key) then return false;end if;
  end loop;
  for field in select key,value from jsonb_each(s->'properties') loop
   if field.value->>'required'='true' and not(v ? field.key) then return false;end if;
  end loop;
 elsif s->>'type'='array' then
  if jsonb_array_length(v)>100 then return false;end if;
  for item in select value from jsonb_array_elements(v) loop if not cms_private.matches_shape(item.value,s->'item') then return false;end if;end loop;
 end if;
 return true;
end; $$;
create function cms_private.content_resources_safe(v jsonb,field text default '') returns boolean language plpgsql immutable set search_path='' as $$
declare item record; link text;
begin
 if jsonb_typeof(v)='object' then
  for item in select key,value from jsonb_each(v) loop if not cms_private.content_resources_safe(item.value,item.key) then return false;end if;end loop;
 elsif jsonb_typeof(v)='array' then
  for item in select value from jsonb_array_elements(v) loop if not cms_private.content_resources_safe(item.value,field) then return false;end if;end loop;
 elsif jsonb_typeof(v)='string' and field ~* '(href|image|photo|logo|video|pdf|material|gallery|coverageImages)$' then
  link:=v#>>'{}';
  if link<>'' and (link !~ '^(https://|/[^/]|/$|#[a-zA-Z0-9-]+$)' or link ~ '[[:space:]"''<>]' or position(chr(92) in link)>0 or link ~ '^https://[^/]*@' or link ~ '^/admin(/|$)' or link ~ '^/docs/legal') then return false;end if;
 end if;
 return true;
end; $$;
create function cms_private.extended_guard() returns trigger language plpgsql set search_path='' as $$
declare k text:=new.draft->>'_kind'; s jsonb; d jsonb:=new.draft->'data'; field text; x jsonb:=new.draft->'design';
begin
 select shape into s from cms_private.editorial_schemas where kind=k;if s is null then return new;end if;
 if not cms_private.matches_shape(d,s) or not cms_private.content_resources_safe(d) or not cms_private.valid_json(new.draft) then raise exception 'Invalid extended content' using errcode='22023';end if;
 if k in ('event','service','training') and (length(btrim(d->>'name')) not between 1 and 120 or d->>'slug' !~ '^[a-z0-9]+(-[a-z0-9]+)*$') then raise exception 'Name and slug required' using errcode='22023';end if;
 if k in ('events-page','services-page','about','orientation','navigation','footer') then
  if new.entity_key<>'main' or d->>'id'<>k then raise exception 'Singleton identity required' using errcode='22023';end if;
  if tg_op='UPDATE' and old.published_version is not null and (new.published_version is null or new.state='archived') then raise exception 'Structural singleton cannot be withdrawn' using errcode='22023';end if;
 end if;
 if k='service' and tg_op='UPDATE' and old.draft->'data'->'ordinal' is distinct from d->'ordinal' then raise exception 'Radial position is structural' using errcode='22023';end if;
 if k='orientation' and d->>'status'<>'Próximamente' then raise exception 'Registration requires legal review' using errcode='22023';end if;
 if k='footer' and length(btrim(d->>'logo'))=0 then raise exception 'Footer and Admin logo required' using errcode='22023';end if;
 if x is not null then
  if jsonb_typeof(x)<>'object' or exists(select 1 from jsonb_object_keys(x) a where a<>all(array['titleSize','color','align','overlay','height'])) then raise exception 'Unsupported graphic controls' using errcode='22023';end if;
  foreach field in array array['overlay','height'] loop
   if x ? field then
    if jsonb_typeof(x->field)<>'number' or (field='overlay' and (x->>field)::numeric not between .4 and .94) or (field='height' and (x->>field)::numeric not between 300 and 820) then raise exception 'Graphic control outside limits' using errcode='22023';end if;
   end if;
  end loop;
 end if;
 if new.draft ? 'seo' then
  if jsonb_typeof(new.draft->'seo')<>'object' or not cms_private.content_resources_safe(new.draft->'seo') then raise exception 'Invalid SEO' using errcode='22023';end if;
  foreach field in array array['title','description','ogTitle','ogDescription','image'] loop if new.draft->'seo' ? field and jsonb_typeof(new.draft->'seo'->field)<>'string' then raise exception 'SEO text required' using errcode='22023';end if;end loop;
  if new.draft->'seo' ? 'noindex' and jsonb_typeof(new.draft->'seo'->'noindex')<>'boolean' then raise exception 'SEO boolean required' using errcode='22023';end if;
 end if;
 return new;
end; $$;
create trigger cms_extended_guard before insert or update on public.cms_documents for each row execute function cms_private.extended_guard();
create function cms_private.module_entries(p_module text) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('moduleId',d.module_id,'key',d.entity_key,'visibility',case when d.state='archived' or d.published_version is null then 'hidden' else 'published' end,'payload',case when d.state='archived' or d.published_version is null then null else v.snapshot end)),'[]')
 from public.cms_documents d left join public.cms_versions v on v.document_id=d.id and v.version_number=d.published_version
 where d.module_id=p_module and p_module in ('events','services','trainings','about','orientation','navigation','footer') and d.draft->>'_kind' is not null and (d.published_version is not null or d.state='archived' or exists(select 1 from public.cms_versions h where h.document_id=d.id))
$$;
create function public.cms_module_entries(p_module text) returns jsonb language sql stable security invoker set search_path='' as $$ select cms_private.module_entries(p_module) $$;
create function cms_private.extended_publish_integrity() returns trigger language plpgsql security definer set search_path='' as $$
declare p jsonb; d jsonb; k text;
begin
 select v.snapshot into p from public.cms_documents c join public.cms_versions v on v.document_id=c.id and v.version_number=c.published_version where c.id=new.id and c.state<>'archived';
 k:=p->>'_kind';d:=p->'data';if p is null or k not in ('event','service','training','training-offering') then return null;end if;
 if exists(select 1 from public.cms_documents c join public.cms_versions v on v.document_id=c.id and v.version_number=c.published_version where c.id<>new.id and c.state<>'archived' and v.snapshot->>'_kind'=k and (v.snapshot->'data'->>'id'=d->>'id' or (k in ('event','service','training') and v.snapshot->'data'->>'slug'=d->>'slug') or (k='training-offering' and v.snapshot->'data'->>'institutionId'=d->>'institutionId' and v.snapshot->'data'->>'trainingProgramId'=d->>'trainingProgramId'))) then raise exception 'Duplicate public identity or slug' using errcode='23505';end if;
 if k='training-offering' and (not exists(select 1 from public.cms_documents c join public.cms_versions v on v.document_id=c.id and v.version_number=c.published_version where c.state<>'archived' and v.snapshot->>'_kind'='institution' and v.snapshot->'data'->>'id'=d->>'institutionId') or not exists(select 1 from public.cms_documents c join public.cms_versions v on v.document_id=c.id and v.version_number=c.published_version where c.state<>'archived' and v.snapshot->>'_kind'='training' and v.snapshot->'data'->>'id'=d->>'trainingProgramId')) then raise exception 'Publish training and institution first' using errcode='23514';end if;
 return null;
end; $$;
create constraint trigger cms_extended_publish_integrity after update of published_version on public.cms_documents deferrable initially deferred for each row execute function cms_private.extended_publish_integrity();
revoke all on function cms_private.matches_shape(jsonb,jsonb),cms_private.content_resources_safe(jsonb,text),cms_private.extended_guard(),cms_private.extended_publish_integrity(),cms_private.module_entries(text),public.cms_module_entries(text) from public,anon,authenticated;
grant execute on function cms_private.module_entries(text),public.cms_module_entries(text) to anon,authenticated;

create or replace function cms_private.editorial_bundle(p_operation text,p_parts jsonb,p_redirects jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare part jsonb; d public.cms_documents; result jsonb; results jsonb:='[]'; rev integer; red jsonb;
begin
 if p_operation not in ('save','publish') or not cms_private.can_perform(case when p_operation='publish' then 'publish' else 'edit' end) then raise exception 'CMS access denied' using errcode='42501'; end if;
 if jsonb_typeof(p_parts)<>'array' or jsonb_array_length(p_parts) not between 1 and 3 then raise exception 'Invalid editorial bundle' using errcode='22023'; end if;
 if (select count(distinct x->>'id') from jsonb_array_elements(p_parts) x)<>jsonb_array_length(p_parts) then raise exception 'Duplicate bundle document' using errcode='22023'; end if;
 for part in select value from jsonb_array_elements(p_parts) order by value->>'id' loop
   select * into d from public.cms_documents where id=(part->>'id')::uuid for update;
   rev:=(part->>'revision')::integer;
   if d.id is null or rev is null or rev<>d.revision then raise exception 'CMS revision conflict' using errcode='40001'; end if;
   if not cms_private.can_content(d.module_id,case when p_operation='publish' then 'publish' else 'edit' end) or d.module_id not in ('home','cities','institutions','careers','events','services','trainings','about','orientation','navigation','footer') or d.draft->>'_kind' is null then raise exception 'CMS access denied' using errcode='42501'; end if;
   if part ? 'payload' and part->'payload' is distinct from d.draft then
     result:=cms_private.mutate_content('save',d.id,null,null,part->'payload',rev,null); rev:=rev+1;
   end if;
   if p_operation='publish' then result:=cms_private.mutate_content('publish',d.id,null,null,null,rev,null);
   else result:=jsonb_build_object('document',(select to_jsonb(row) from public.cms_documents row where row.id=d.id)); end if;
   results:=results||jsonb_build_array(result);
 end loop;
 -- One atomic published catalog: reject duplicate identities/routes and broken relations.
 if p_operation='publish' then
   if exists(select 1 from public.cms_documents a join public.cms_versions av on av.document_id=a.id and av.version_number=a.published_version
     join public.cms_documents b on b.id<>a.id and b.state<>'archived' join public.cms_versions bv on bv.document_id=b.id and bv.version_number=b.published_version
     where a.state<>'archived' and av.snapshot->>'_kind'=bv.snapshot->>'_kind' and av.snapshot->>'_kind' in ('city','career','brand','institution')
      and av.snapshot->'data'->>'slug'=bv.snapshot->'data'->>'slug'
      and (av.snapshot->>'_kind'<>'institution' or av.snapshot->'data'->>'cityId'=bv.snapshot->'data'->>'cityId')) then raise exception 'Duplicate public slug' using errcode='23505'; end if;
   for red in select value from jsonb_array_elements(coalesce(p_redirects,'[]')) loop
     if exists(select 1 from public.cms_redirects where source=red->>'to') then raise exception 'Redirect chains not allowed' using errcode='22023'; end if;
     insert into public.cms_redirects(source,destination,created_by) values(red->>'from',red->>'to',auth.uid()) on conflict(source) do update set destination=excluded.destination,created_by=excluded.created_by;
   end loop;
 end if;
 return results;
end; $$;





